package org.jsoup.internal;

import org.junit.Test;
import static org.junit.Assert.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class StringUtil_ESTest_test30 extends StringUtil_ESTest_scaffolding {

    /**
     * Code point 13 is the carriage return ('\r'), which the HTML spec treats
     * as whitespace, so {@link StringUtil#isWhitespace(int)} should return true.
     */
    @Test(timeout = 4000)
    public void isWhitespaceReturnsTrueForCarriageReturn() throws Throwable {
        int carriageReturnCodePoint = '\r'; // == 13

        boolean isWhitespace = StringUtil.isWhitespace(carriageReturnCodePoint);

        assertTrue(isWhitespace);
    }
}
